// verify containment: inside polygon
function inside(b){
  const n=9,R=260,CX=400,CY=400,a0=-Math.PI/2+s.poly.angle;
  let insideAll=true;
  for(let i=0;i<n;i++){
    const A={x:CX+Math.cos(a0+i*2*Math.PI/n)*R,y:CY+Math.sin(a0+i*2*Math.PI/n)*R};
    const B={x:CX+Math.cos(a0+(i+1)*2*Math.PI/n)*R,y:CY+Math.sin(a0+(i+1)*2*Math.PI/n)*R};
    // cross product sign: for CCW polygon interior on left; our order with y down... just check distance to each edge line <=0 relative to center
    const ex=B.x-A.x, ey=B.y-A.y;
    const v = (b.x-A.x)*ey - (b.y-A.y)*ex;
    const cv = (CX-A.x)*ey - (CY-A.y)*ex;
    if (Math.sign(v)!==Math.sign(cv)) insideAll=false;
  }
  return insideAll;
}
